vec3 palette(float t) {
    vec3 a = vec3(0.5,0.5,0.5);
    vec3 b = vec3(0.5,0.5,0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0., 0.15, 0.2);

    return a + b * cos(6.28318 * (c*t+d));
}

float sdTriPrism( vec3 p, vec2 h )
{
  vec3 q = abs(p);
  return max(q.z-h.y,max(q.x*0.866025+p.y*0.5,-p.y)-h.x*0.5);
}

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, .0)) + min(max(q.x, max(q.y, q.z)), .0);
}

float sdOctahedron(vec3 p, float s) {
    p = abs(p);
    return (p.x + p.y + p.z - s) * 0.57735027;

}

mat2 rot2D(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

vec3 rot3D(vec3 p, vec3 axis, float angle) {
    // Rodrigues' rotation formula
    return mix(dot(axis, p) * axis, p, cos(angle)) 
            + cross(axis, p) * sin(angle);
}

float smin( float a, float b, float k) {
    float h = max(k - abs(a-b), 0.0) / k;
    return min(a,b) - h*h*h*k*(1.0/6.0);
}

float map(vec3 p) {
      vec3 q = p;
    //p.z += iTime * 1.;  
    p.xy = (fract(p.xy) - .5);
    p.z = mod(p.z, .25) - 0.125;
    p.xy *= rot2D(iTime*3. + q.z * 1.2);


    float box;// = sdBox(p, vec3(0.1,0.1, 0.125));
    box = sdTriPrism(p, vec2(0.15, 0.125));

    return box;
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2. - iResolution.xy) / iResolution.y;
    vec2 m = (iMouse.xy * 2. - iResolution.xy) / iResolution.y;

    // simulate mouse movement if is not pressed
    if (iMouse.z < 0. || m.y <= -1.) m = vec2(cos(iTime*.1), 0.);
    // Initialization
    vec3 ro = vec3(0, 0, -3);
    vec3 rd = normalize(vec3(uv, 1));

    // Camera movement
    ro.yz *= rot2D(-m.y);
    rd.yz *= rot2D(-m.y);

    ro.xz *= rot2D(-m.x);
    rd.xz *= rot2D(-m.x);

    vec3 col = vec3(0);



    float t = 0.; // total distance travelled
    int i;
    for (i = 0; i < 80; i++) {
        vec3 p = ro + rd * t; // position along the ray

        p.xy *= rot2D(t*.15);

        p.y += sin(t*(m.y+1.))*.2; // wiggle the ray

        float d = map(p); // current distance to the scene

        t += d; // march the ray

        if (d < .0001) break;
        if (t > 80.) break;
    }

    col = palette(t * 0.04 - exp(float(i)*.0003));

    // apply lightness curve
    float p = 1.;
    p = 2. - exp(float(i)*0.008);
    col.x = pow(col.x, p);
    col.y = pow(col.y, p);
    col.z = pow(col.z, p);

    // Output to screen
    fragColor = vec4(col,1);
}
